import type { Channel } from "amqplib";

export const EVENTS_EXCHANGE = "events.exchange";
export const EVENTS_DLX_EXCHANGE = "events.dlx.exchange";
export const EVENTS_QUEUE = "user.events.queue";
export const EVENTS_DLQ = "events.dlq";
export const USER_CREATED_ROUTING_KEY = "user.created";
export const MAX_DELIVERY_ATTEMPTS = 5;

export async function setupRabbitMqTopology(
  channel: Channel,
): Promise<void> {
  await channel.assertExchange(EVENTS_EXCHANGE, "topic", {
    durable: true,
  });
  await channel.assertExchange(EVENTS_DLX_EXCHANGE, "topic", {
    durable: true,
  });

  await channel.assertQueue(EVENTS_DLQ, {
    durable: true,
    arguments: {
      "x-queue-type": "quorum",
    },
  });
  await channel.bindQueue(
    EVENTS_DLQ,
    EVENTS_DLX_EXCHANGE,
    "#",
  );

  await channel.assertQueue(EVENTS_QUEUE, {
    durable: true,
    arguments: {
      "x-queue-type": "quorum",
      "x-dead-letter-exchange": EVENTS_DLX_EXCHANGE,
      "x-delivery-limit": MAX_DELIVERY_ATTEMPTS,
    },
  });
  await channel.bindQueue(
    EVENTS_QUEUE,
    EVENTS_EXCHANGE,
    USER_CREATED_ROUTING_KEY,
  );
}
